3	namespace App\Support;
4	
5	use Illuminate\Database\Query\Builder;
6	use Illuminate\Http\Request;
7	
8	/**
9	 * PaginationBase / PaginationQuery from mealie/schema/response/pagination.py.
10	 * Envelope keys stay snake_case (per_page, total_pages) because PaginationBase is not a MealieModel;
11	 * items are whatever the caller maps them to.
12	 *
13	 * Not implemented here: queryFilter language (mealie/services/query_filter), orderBy on related
14	 * fields, random order with paginationSeed. Areas that need them must list them as not implemented.
15	 */
16	class Pagination
17	{
18	    /**
19	     * @param  callable(object):array  $map  row -> API item
20	     * @param  string  $route  path used for next/previous, without the /api prefix (e.g. "/foods")
21	     */
22	    public static function page(Request $request, Builder $query, callable $map, string $route, ?string $defaultOrder = null): array
23	    {
24	        $page = (int) ($request->query('page', 1));
25	        $perPage = (int) ($request->query('perPage', $request->query('per_page', 50)));
26	        $orderBy = $request->query('orderBy');
27	        $direction = strtolower((string) $request->query('orderDirection', 'desc')) === 'asc' ? 'asc' : 'desc';
28	
29	        $total = (clone $query)->count();
30	        if ($perPage === -1) {
31	            $perPage = max($total, 1);
32	        }
33	        $perPage = max($perPage, 1);
34	        $totalPages = (int) ceil($total / $perPage);
35	        $page = max($page, 1);
36	
37	        if (is_string($orderBy) && $orderBy !== '' && preg_match('/^[A-Za-z_]+$/', $orderBy)) {
38	            $query->orderBy(self::snake($orderBy), $direction);
39	        } elseif ($defaultOrder !== null) {
40	            $query->orderBy($defaultOrder, $direction);
41	        }
42	
43	        $rows = $query->offset(($page - 1) * $perPage)->limit($perPage)->get();
44	
45	        $params = [
46	            'orderBy' => $orderBy ?? 'None',
47	            'orderByNullPosition' => $request->query('orderByNullPosition', 'None'),
48	            'orderDirection' => $direction,
49	            'queryFilter' => $request->query('queryFilter', 'None'),
50	            'paginationSeed' => $request->query('paginationSeed', 'None'),
51	        ];
52	
53	        return [
54	            'page' => $page,
55	            'per_page' => $perPage,
56	            'total' => $total,
57	            'total_pages' => $totalPages,
58	            'items' => $rows->map(fn ($row) => $map($row))->values()->all(),
59	            'next' => $page >= $totalPages ? null : $route.'?'.http_build_query($params + ['page' => $page + 1, 'perPage' => $perPage]),
60	            'previous' => $page <= 1 ? null : $route.'?'.http_build_query($params + ['page' => $page - 1, 'perPage' => $perPage]),
61	        ];
62	    }
63	
64	    public static function snake(string $camel): string
65	    {
66	        return strtolower(preg_replace('/(?<!^)[A-Z]/', '_$0', $camel));
67	    }
68	}
