3	namespace App\Support;
4	
5	use Illuminate\Http\JsonResponse;
6	use Illuminate\Http\Request;
7	
8	class Json
9	{
10	    /** snake_case -> camelCase like humps.camelize used by MealieModel. */
11	    public static function camel(string $key): string
12	    {
13	        return lcfirst(str_replace(' ', '', ucwords(str_replace('_', ' ', $key))));
14	    }
15	
16	    public static function camelKeys(array $data): array
17	    {
18	        $out = [];
19	        foreach ($data as $key => $value) {
20	            $out[is_string($key) ? self::camel($key) : $key] = is_array($value) ? self::camelKeys($value) : $value;
21	        }
22	
23	        return $out;
24	    }
25	
26	    /** JSON response that keeps "{}" for empty objects and does not escape slashes/unicode. */
27	    public static function respond(mixed $data, int $status = 200): JsonResponse
28	    {
29	        return response()->json($data, $status, [], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION);
30	    }
31	
32	    /**
33	     * Request body as FastAPI would parse it for a Pydantic model parameter:
34	     * must be a JSON object, otherwise 422.
35	     */
36	    public static function body(Request $request): array
37	    {
38	        $raw = $request->getContent();
39	        $decoded = json_decode($raw === '' ? 'null' : $raw, true);
40	        if (! is_array($decoded) || array_is_list($decoded) && $decoded !== []) {
41	            Errors::validation('Input should be a valid dictionary or object to extract fields from at body');
42	        }
43	
44	        return $decoded;
45	    }
46	}
