3	namespace App\Support;
4	
5	/**
6	 * SQLite stores naive UTC like "2026-08-06 13:35:24.307376".
7	 * MealieModel.set_tz_info marks datetimes as UTC, so the API returns "2026-08-06T13:35:24.307376Z".
8	 */
9	class Dates
10	{
11	    public static function out(?string $value): ?string
12	    {
13	        if ($value === null || $value === '') {
14	            return null;
15	        }
16	        $value = str_replace(' ', 'T', $value);
17	        if (preg_match('/(Z|[+-]\d{2}:?\d{2})$/', $value)) {
18	            return $value;
19	        }
20	
21	        return $value.'Z';
22	    }
23	
24	    /** Pydantic `date` fields: "2026-08-06". */
25	    public static function date(?string $value): ?string
26	    {
27	        return $value === null || $value === '' ? null : substr($value, 0, 10);
28	    }
29	
30	    /** Current UTC time in the stored format. */
31	    public static function nowDb(): string
32	    {
33	        return (new \DateTimeImmutable('now', new \DateTimeZone('UTC')))->format('Y-m-d H:i:s.u');
34	    }
35	}
