from functools import cached_property
from uuid import UUID

from fastapi import Depends, HTTPException
from pydantic import UUID4

from mealie.routes._base.base_controllers import BaseUserController
from mealie.routes._base.controller import controller
from mealie.routes._base.routers import UserAPIRouter
from mealie.schema.group.group_preferences import ReadGroupPreferences, UpdateGroupPreferences
from mealie.schema.group.group_statistics import GroupStorage
from mealie.schema.response.pagination import PaginationBase, PaginationQuery
from mealie.schema.user.user import GroupSummary, UserSummary
from mealie.services.group_services.group_service import GroupService

router = UserAPIRouter(prefix="/groups", tags=["Groups: Self Service"])


@controller(router)
class GroupSelfServiceController(BaseUserController):
    @cached_property
    def service(self) -> GroupService:
        return GroupService(self.group_id, self.repos)

    @router.get("/self", response_model=GroupSummary)
    def get_logged_in_user_group(self):
        """Returns the Group Data for the Current User"""
        return self.group.cast(GroupSummary)

    @router.get("/members", response_model=PaginationBase[UserSummary])
    def get_group_members(self, q: PaginationQuery = Depends()):
        """Returns all users belonging to the current group"""
        response = self.repos.users.page_all(q, override=UserSummary)
        response.set_pagination_guides(router.url_path_for("get_group_members"), q.model_dump())
        return response

    @router.get("/members/{username_or_id}", response_model=UserSummary)
    def get_group_member(self, username_or_id: str | UUID4):
        """Returns a single user belonging to the current group"""

        try:
            UUID(username_or_id)
            key = "id"
        except ValueError:
            key = "username"

        private_user = self.repos.users.get_one(username_or_id, key)
        if not private_user:
            raise HTTPException(status_code=404, detail="User Not Found")

        return private_user.cast(UserSummary)

    @router.get("/preferences", response_model=ReadGroupPreferences)
    def get_group_preferences(self):
        return self.group.preferences

    @router.put("/preferences", response_model=ReadGroupPreferences)
    def update_group_preferences(self, new_pref: UpdateGroupPreferences):
        self.checks.can_manage()
        return self.repos.group_preferences.update(self.group_id, new_pref)

    @router.get("/storage", response_model=GroupStorage)
    def get_storage(self):
        return self.service.calculate_group_storage()

from fastapi import Depends, HTTPException

from mealie.routes._base.base_controllers import BaseUserController
from mealie.routes._base.controller import controller
from mealie.routes._base.routers import UserAPIRouter
from mealie.schema.household.household import HouseholdSummary
from mealie.schema.response.pagination import PaginationBase, PaginationQuery

router = UserAPIRouter(prefix="/groups/households", tags=["Groups: Households"])


@controller(router)
class GroupHouseholdsController(BaseUserController):
    @router.get("", response_model=PaginationBase[HouseholdSummary])
    def get_all_households(self, q: PaginationQuery = Depends(PaginationQuery)):
        response = self.repos.households.page_all(pagination=q, override=HouseholdSummary)

        response.set_pagination_guides(router.url_path_for("get_all_households"), q.model_dump())
        return response

    @router.get("/{household_slug}", response_model=HouseholdSummary)
    def get_one_household(self, household_slug: str):
        household = self.repos.households.get_by_slug_or_id(household_slug)

        if not household:
            raise HTTPException(status_code=404, detail="Household not found")
        return household.cast(HouseholdSummary)

from functools import cached_property

from fastapi import APIRouter, Depends
from pydantic import UUID4

from mealie.routes._base.base_controllers import BaseCrudController
from mealie.routes._base.controller import controller
from mealie.routes._base.mixins import HttpRepo
from mealie.routes._base.routers import MealieCrudRoute
from mealie.schema.labels import (
    MultiPurposeLabelCreate,
    MultiPurposeLabelOut,
    MultiPurposeLabelSummary,
    MultiPurposeLabelUpdate,
)
from mealie.schema.labels.multi_purpose_label import MultiPurposeLabelPagination
from mealie.schema.response.pagination import PaginationQuery
from mealie.services.event_bus_service.event_types import EventLabelData, EventOperation, EventTypes
from mealie.services.group_services.labels_service import MultiPurposeLabelService

router = APIRouter(prefix="/groups/labels", tags=["Groups: Multi Purpose Labels"], route_class=MealieCrudRoute)


@controller(router)
class MultiPurposeLabelsController(BaseCrudController):
    @cached_property
    def service(self):
        return MultiPurposeLabelService(self.repos)

    @cached_property
    def repo(self):
        if not self.user:
            raise Exception("No user is logged in.")

        return self.repos.group_multi_purpose_labels

    # =======================================================================
    # CRUD Operations

    @property
    def mixins(self) -> HttpRepo:
        return HttpRepo(self.repo, self.logger, self.registered_exceptions, self.t("generic.server-error"))

    @router.get("", response_model=MultiPurposeLabelPagination)
    def get_all(self, q: PaginationQuery = Depends(PaginationQuery), search: str | None = None):
        response = self.repo.page_all(
            pagination=q,
            override=MultiPurposeLabelSummary,
            search=search,
        )

        response.set_pagination_guides(router.url_path_for("get_all"), q.model_dump())
        return response

    @router.post("", response_model=MultiPurposeLabelOut)
    def create_one(self, data: MultiPurposeLabelCreate):
        try:
            new_label = self.service.create_one(data)
        except Exception as ex:
            self.mixins.handle_exception(ex)
            raise  # handle_exception always raises; this satisfies static analysis
        self.publish_event(
            event_type=EventTypes.label_created,
            document_data=EventLabelData(operation=EventOperation.create, label_id=new_label.id),
            group_id=new_label.group_id,
            household_id=None,
            message=self.t("notifications.generic-created", name=new_label.name),
        )
        return new_label

    @router.get("/{item_id}", response_model=MultiPurposeLabelOut)
    def get_one(self, item_id: UUID4):
        return self.mixins.get_one(item_id)

    @router.put("/{item_id}", response_model=MultiPurposeLabelOut)
    def update_one(self, item_id: UUID4, data: MultiPurposeLabelUpdate):
        label = self.mixins.update_one(data, item_id)
        self.publish_event(
            event_type=EventTypes.label_updated,
            document_data=EventLabelData(operation=EventOperation.update, label_id=label.id),
            group_id=label.group_id,
            household_id=None,
            message=self.t("notifications.generic-updated", name=label.name),
        )
        return label

    @router.delete("/{item_id}", response_model=MultiPurposeLabelOut)
    def delete_one(self, item_id: UUID4):
        label = self.mixins.delete_one(item_id)
        if label:
            self.publish_event(
                event_type=EventTypes.label_deleted,
                document_data=EventLabelData(operation=EventOperation.delete, label_id=label.id),
                group_id=label.group_id,
                household_id=None,
