$where = function ($q) use ($tokens, $columns, $table) {
    $any = false;
    foreach ($columns as $column) {
        foreach ($tokens as $token) {
            $q->orWhereRaw("{$table}.{$column} LIKE ?", ['%'.$token.'%']);
            $any = true;
        }
    }
    if (! $any) {
        // or_() with no clauses renders as false
        $q->whereRaw('0 = 1');
    }
};

