function req($port, $m, $p, $b, $who, $tok) {
  $ch = curl_init("http://127.0.0.1:$port/api$p");
  $h = ["Content-Type: application/json"];
  if (isset($tok[$who])) $h[] = "Authorization: Bearer ".$tok[$who];
  curl_setopt_array($ch, [CURLOPT_CUSTOMREQUEST => $m, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => $h]);
  if ($b !== "") curl_setopt($ch, CURLOPT_POSTFIELDS, $b);
  $out = curl_exec($ch); $s = curl_getinfo($ch, CURLINFO_HTTP_CODE);
  return [$s, $out];
}
function norm($v, $ignore) { if (is_array($v)) { $o = []; foreach ($v as $k => $x) { if (in_array($k, $ignore, true)) continue; $o[$k] = norm($x, $ignore);} if (!array_is_list($o)) ksort($o); return $o;} return $v; }
$ignore = getenv("IGNORE") ? explode(",", getenv("IGNORE")) : [];
$ok = 0; $bad = 0;
foreach (file($argv[1], FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
  if ($line[0] === "#") continue;
  [$m, $p, $b, $w] = array_pad(explode("|", $line, 4), 4, "admin"); if ($w === "") $w = "admin";
  [$s1, $o1] = req(9000, $m, $p, $b, $w, $tok); [$s2, $o2] = req(9014, $m, $p, $b, $w, $tok);
  $j1 = json_decode($o1, true); $j2 = json_decode($o2, true);
  if ($s1 == 422 && $s2 == 422) { $same = true; } else { $same = $s1 == $s2 && norm($j1, $ignore) == norm($j2, $ignore); }
  if ($same) { $ok++; echo "MATCH $s1 $m $p ($w)\n"; }
  else { $bad++; echo "DIFF  $m $p ($w)\n   py  $s1 ".substr($o1,0,600)."\n   php $s2 ".substr($o2,0,600)."\n"; }
}
echo "match=$ok diff=$bad\n";
EOF
echo ok'

